package com.jobtracker.model;
import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.*; import static com.jobtracker.model.Enums.Status;
@Entity @Getter @Setter @NoArgsConstructor @Builder @AllArgsConstructor
public class JobApplication { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) User user; @Column(nullable=false) String company; @Column(nullable=false) String jobTitle; String location; String jobUrl; String salary; String source; @Enumerated(EnumType.STRING) Status status; LocalDate appliedDate; LocalDate closingDate; @Column(length=4000) String description; LocalDateTime createdAt; LocalDateTime updatedAt; @PrePersist void p(){createdAt=LocalDateTime.now();updatedAt=createdAt;if(status==null)status=Status.SAVED;} @PreUpdate void u(){updatedAt=LocalDateTime.now();} }